{
  "findings": [
    {
      "check_id": "CKV_AWS_5",
      "title": "Ensure all data stored in the Elasticsearch is securely encrypted at rest",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain 'log_search_database' has 'encrypt_at_rest' set to false, which means data stored in the Elasticsearch is not securely encrypted at rest."
    },
    {
      "check_id": "CKV_AWS_6",
      "title": "Ensure all Elasticsearch has node-to-node encryption enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain 'log_search_database' is missing 'node_to_node_encryption' configuration, which is not enabled by default, potentially leaving the data in transit unencrypted."
    },
    {
      "check_id": "CKV_AWS_84",
      "title": "Ensure Elasticsearch Domain Logging is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain 'log_search_database' is missing 'log_publishing_options' configuration for logging, which is not enabled by default."
    },
    {
      "check_id": "CKV_AWS_317",
      "title": "Ensure Elasticsearch Domain Audit Logging is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain 'log_search_database' is missing 'log_publishing_options' configuration for audit logging, which is not enabled by default."
    },
    {
      "check_id": "CKV2_AWS_59",
      "title": "Ensure ElasticSearch/OpenSearch has dedicated master node enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "The Elasticsearch domain 'log_search_database' has 'instance_count' set to 2 but does not explicitly configure a dedicated master node, which could impact availability."
    }
  ],
  "patched_code": "resource "aws_elasticsearch_domain" "log_search_database" {
  domain_name           = "enterprise-log-analytics-es"
  elasticsearch_version = "7.10"
  cluster_config {
    instance_type  = var.elasticsearch_instance_type
    instance_count = 2
    dedicated_master_enabled = true
    dedicated_master_count   = 3
    dedicated_master_type    = "r6g.large.elasticsearch"
  }
  vpc_options {
    subnet_ids         = [aws_subnet.data_subnet_az1.id]
    security_group_ids = [aws_security_group.elasticsearch_sg.id]
  }
  ebs_options {
    ebs_enabled = true
    volume_size = 20
    volume_type = "gp2"
  }
  encrypt_at_rest {
    enabled = true
  }
  node_to_node_encryption {
    enabled = true
  }
  log_publishing_options {
    log_type                 = "INDEX_SLOW_LOGS"
    cloudwatch_log_group_arn = "${aws_cloudwatch_log_group.es_log_group.arn}"
    enabled                  = true
  }
  log_publishing_options {
    log_type                 = "SEARCH_SLOW_LOGS"
    cloudwatch_log_group_arn = "${aws_cloudwatch_log_group.es_log_group.arn}"
    enabled                  = true
  }
  log_publishing_options {
    log_type                 = "ES_APPLICATION_LOGS"
    cloudwatch_log_group_arn = "${aws_cloudwatch_log_group.es_log_group.arn}"
    enabled                  = true
  }
  log_publishing_options {
    log_type                 = "AUDIT_LOGS"
    cloudwatch_log_group_arn = "${aws_cloudwatch_log_group.es_log_group.arn}"
    enabled                  = true
  }
}",
  "fix_summary": "Enabled encryption at rest, node-to-node encryption, and logging for the Elasticsearch domain. Configured dedicated master nodes for high availability."
}
